// prisma/schema.prisma
generator client {
  provider = "prisma-client"
  output   = "../app/generated/prisma"
}

datasource db {
  provider = "sqlite"
}

model Tarefa {
  id       Int      @id @default(autoincrement())
  titulo   String
  feita    Boolean  @default(false)
  criadaEm DateTime @default(now())
}

// lib/db.ts -- uma unica conexao com o banco para o projeto todo
import { PrismaBetterSqlite3 } from "@prisma/adapter-better-sqlite3";
import { PrismaClient } from "@/app/generated/prisma/client";

const adapter = new PrismaBetterSqlite3({
  url: process.env.DATABASE_URL ?? "file:./dev.db",
});

// Em desenvolvimento, o Next.js recarrega os arquivos a cada
// alteracao; guardar o cliente em globalThis evita criar um
// cliente novo a cada recarga.
const globalParaPrisma = globalThis as unknown as {
  prisma?: PrismaClient;
};

export const db =
  globalParaPrisma.prisma ?? new PrismaClient({ adapter });

if (process.env.NODE_ENV !== "production") {
  globalParaPrisma.prisma = db;
}

// app/tarefas/actions.ts -- agora gravando no banco
"use server";

import { revalidatePath } from "next/cache";
import { db } from "@/lib/db";

export async function criarTarefa(formData: FormData) {
  const titulo = String(formData.get("titulo") ?? "").trim();
  if (!titulo) return;

  await db.tarefa.create({ data: { titulo } });
  revalidatePath("/tarefas");
}

export async function marcarFeita(id: number) {
  await db.tarefa.update({ where: { id }, data: { feita: true } });
  revalidatePath("/tarefas");
}

export async function excluirTarefa(id: number) {
  await db.tarefa.delete({ where: { id } });
  revalidatePath("/tarefas");
}

